//! `cargo xtask bindgen-mpv`: regenerate `crates/sucrose-engine-mpv/src/sys.rs` from the pinned `client.h`.
//!
//! The generated file is committed, so CI and normal builds need no libclang (D-013). Only this task, built with
//! the `bindgen` cargo feature, uses it.

use std::process::ExitCode;

/// `cargo xtask bindgen-mpv [--header <path>]`; defaults to the header that `fetch-engines` extracted for x86_64.
pub fn run(args: &[String]) -> ExitCode {
    match generate(args) {
        Ok(()) => ExitCode::SUCCESS,
        Err(message) => {
            eprintln!("failed: {message}");
            ExitCode::FAILURE
        }
    }
}

#[cfg(not(feature = "bindgen"))]
fn generate(_args: &[String]) -> Result<(), String> {
    Err("rebuild with: cargo run -p xtask --features bindgen -- bindgen-mpv".to_owned())
}

/// Functions the engine crate may call; everything else in `client.h` stays out of the bindings.
#[cfg(feature = "bindgen")]
const FUNCTIONS: &[&str] = &[
    "mpv_client_api_version",
    "mpv_error_string",
    "mpv_free",
    "mpv_create",
    "mpv_initialize",
    "mpv_terminate_destroy",
    "mpv_set_option_string",
    "mpv_set_property",
    "mpv_set_property_string",
    "mpv_get_property",
    "mpv_get_property_string",
    "mpv_command",
    "mpv_observe_property",
    "mpv_wait_event",
    "mpv_wakeup",
    "mpv_set_wakeup_callback",
    "mpv_load_config_file",
    "mpv_request_log_messages",
];

/// Types (and the constants of the enums among them) the engine crate reads.
#[cfg(feature = "bindgen")]
const TYPES: &[&str] = &[
    "mpv_handle",
    "mpv_event",
    "mpv_event_id",
    "mpv_event_property",
    "mpv_event_end_file",
    "mpv_event_log_message",
    "mpv_format",
    "mpv_error",
    "mpv_end_file_reason",
];

#[cfg(feature = "bindgen")]
fn generate(args: &[String]) -> Result<(), String> {
    use std::path::PathBuf;

    let header = match args {
        [] => crate::target_dir()
            .join("engines")
            .join("x86_64")
            .join("include")
            .join("mpv")
            .join("client.h"),
        [flag, path] if flag == "--header" => PathBuf::from(path),
        _ => return Err("usage: cargo xtask bindgen-mpv [--header <path>]".to_owned()),
    };
    if !header.is_file() {
        return Err(format!(
            "{} not found; run cargo xtask fetch-engines first",
            header.display()
        ));
    }
    let provenance = crate::fetch_engines::pin_summary("x86_64")?;

    let mut builder = bindgen::Builder::default()
        .header(header.to_string_lossy())
        // The pinned DLL is a Windows build; -ffreestanding keeps clang from wanting a system C library.
        .clang_args(["--target=x86_64-pc-windows-msvc", "-ffreestanding"])
        .dynamic_library_name("Mpv")
        .dynamic_link_require_all(true)
        // x86_64 layout asserts would fail to compile for the i686 build.
        .layout_tests(false)
        // Edition 2024 denies unsafe_op_in_unsafe_fn; the generated wrappers must carry their own unsafe blocks.
        .wrap_unsafe_ops(true)
        .disable_header_comment();
    for function in FUNCTIONS {
        builder = builder.allowlist_function(function);
    }
    for ty in TYPES {
        builder = builder.allowlist_type(ty);
    }
    let bindings = builder.generate().map_err(|e| format!("bindgen failed: {e}"))?;

    let text = format!(
        "// Generated by `cargo xtask bindgen-mpv` from client.h of {provenance}.\n\
         // Do not edit by hand; change xtask/src/bindgen_mpv.rs and regenerate.\n\n{bindings}"
    );
    let destination = crate::workspace_root()
        .join("crates")
        .join("sucrose-engine-mpv")
        .join("src")
        .join("sys.rs");
    std::fs::write(&destination, text).map_err(|e| format!("cannot write {}: {e}", destination.display()))?;
    println!("wrote {}", destination.display());
    Ok(())
}
